use axum::{extract::{Path, State}, response::IntoResponse, Json};
use uuid::Uuid;
use crate::application::dto::{DisbursementRequest, DisbursementResponse};
use crate::application::error::ApiError;
use crate::app_state::AppState;

pub struct LoanHandler;

impl LoanHandler {
    // BUG: no Header(idempotency_key) extractor; no dedup-store call;
    // no replay branch. Money-moving handler with NO idempotency.
    #[tracing::instrument(skip(state, req), fields(loan_id = %loan_id))]
    pub async fn disburse(
        State(state): State<AppState>,
        Path(loan_id): Path<Uuid>,
        Json(req): Json<DisbursementRequest>,
    ) -> Result<Json<DisbursementResponse>, ApiError> {
        let ledger_id = state.ledger.disburse(loan_id, req.amount_cents).await
            .map_err(|_| ApiError::Dependency)?;
        sqlx::query!(
            "INSERT INTO loan_disbursements (loan_id, amount_cents, ledger_id) VALUES ($1, $2, $3)",
            loan_id, req.amount_cents, ledger_id
        ).execute(&state.pool).await.map_err(|_| ApiError::Dependency)?;
        // BUG: no audit event emitted either — claim says loan.disbursed but code does not emit.
        Ok(Json(DisbursementResponse { ledger_id }))
    }
}

